const int PIN_LDR = A0;
const int BUZZER  = 8;
const int LED     = 13;

int  darkValue = 0;        // ค่าตอนปิดฝา จำไว้ตอนเริ่ม
bool alarmOn   = false;

void setup() {
  Serial.begin(9600);
  pinMode(BUZZER, OUTPUT);
  pinMode(LED, OUTPUT);

  Serial.println("ปิดฝากล่องไว้ กำลังจำค่าความมืด...");
  delay(3000);
  darkValue = analogRead(PIN_LDR);       // จำสภาพตอนปิดฝา
  Serial.print("ค่าตอนปิดฝา = ");
  Serial.println(darkValue);
  Serial.println("พร้อมแล้ว ลองเปิดฝาดู");
}

void loop() {
  int light = analogRead(PIN_LDR);
  int diff  = abs(light - darkValue);

  if (diff > 120) {                      // แสงเปลี่ยนไปมาก = ฝาถูกเปิด
    if (!alarmOn) {
      alarmOn = true;
      Serial.println("!! มีคนเปิดกล่อง !!");
    }
    digitalWrite(LED, HIGH);
    beep(2500, 100);
    digitalWrite(LED, LOW);
    delay(100);
  } else {
    if (alarmOn) { alarmOn = false; Serial.println("ปิดฝาแล้ว ปลอดภัย"); }
    delay(100);
  }
}

void beep(int freq, int ms) {          // บัซเซอร์ passive ใช้ tone()
  tone(BUZZER, freq);
  delay(ms);
  noTone(BUZZER);
}

