int  alarms = 0;
bool lastState;

void setup() {
  pinMode(PIN_SHOCK, INPUT_PULLUP);       // กันขาลอย ไม่ให้นับผีหลอก
  pinMode(BUZZER, OUTPUT);
  pinMode(LED, OUTPUT);
  Serial.begin(9600);
  delay(1000);                            // รอให้นิ่งก่อนจำสถานะเริ่มต้น
  lastState = digitalRead(PIN_SHOCK);
  Serial.println("ระบบกันขโมยพร้อม ลองเขย่าดู");
}

void loop() {
  bool now = digitalRead(PIN_SHOCK);

  if (now != lastState) {                 // สถานะเปลี่ยน = มีการสั่น
    alarms++;
    Serial.print("!! ตรวจพบการสั่น ครั้งที่ ");
    Serial.print(alarms);
    Serial.println(" !!");
    siren();
    delay(300);                           // หน่วงกันนับซ้ำจากการสั่นค้าง
    lastState = digitalRead(PIN_SHOCK);
    return;
  }
  lastState = now;
}

void siren() {                            // เสียงไซเรนขึ้นลง 3 วินาที
  unsigned long start = millis();
  while (millis() - start < 3000) {
    digitalWrite(LED, HIGH);
    for (int f = 800; f < 2000; f += 60) { tone(BUZZER, f); delay(8); }
    digitalWrite(LED, LOW);
    for (int f = 2000; f > 800; f -= 60) { tone(BUZZER, f); delay(8); }
  }
  noTone(BUZZER);
  digitalWrite(LED, LOW);
  Serial.println("ไซเรนหยุด กลับสู่โหมดเฝ้าระวัง");
}

