  if (state == HIGH && lastState == LOW && millis() - lastClap > 500) {
    lastClap = millis();
    lampOn = !lampOn;
    digitalWrite(LED, lampOn);

    if (lampOn) {
      Serial.println("ปรบมือ -> เปิดไฟ");
    } else {
      Serial.println("ปรบมือ -> ปิดไฟ");
    }
  }
  lastState = state;
}

