// มาตรวัดเสียง จอแสดงผล โชว์แถบกราฟและค่าสูงสุดที่เคยทำได้ แข่งกันตะโกนได้

#include <Wire.h>
#include <LiquidCrystal_I2C.h>
LiquidCrystal_I2C lcd(0x27, 16, 2);

const int PIN_A  = A0;
const int BUZZER = 8;

int quiet = 0, limit = 0, record = 0;

void setup() {
  pinMode(BUZZER, OUTPUT);
  lcd.init(); lcd.backlight();

  lcd.print("Calibrating...");
  lcd.setCursor(0, 1);
  lcd.print("Keep quiet 3 sec");
  long sum = 0;
  for (int i = 0; i < 60; i++) { sum += peak(); delay(50); }
  quiet  = sum / 60;
  limit  = quiet + 150;
  record = quiet;
  lcd.clear();
}

void loop() {
  int level = peak();
  if (level > record) record = level;             // เก็บสถิติเสียงดังที่สุด

  lcd.setCursor(0, 0);
  lcd.print("Now ");  lcd.print(level);   lcd.print("    ");
  lcd.setCursor(9, 0);
  lcd.print("Max ");  lcd.print(record);  lcd.print("  ");

  lcd.setCursor(0, 1);
  int bars = map(level, quiet, quiet + 300, 0, 16);
  bars = constrain(bars, 0, 16);
  for (int i = 0; i < 16; i++) lcd.print(i < bars ? (char)255 : ' ');

  if (level > limit) tone(BUZZER, 2500, 120);
  delay(120);
}

int peak() {                                      // ค่าสูงสุดใน 50 มิลลิวินาที
  int p = 0;
  unsigned long start = millis();
  while (millis() - start < 50) {
    int v = analogRead(PIN_A);
    if (v > p) p = v;
  }
  return p;
}

