// ใช้ขา AO แทน DO เพื่อไม่ต้องพึ่งการหมุนน็อตบนโมดูล

const int PIN_A  = A0;
const int BUZZER = 8;
const int LED    = 13;

int  closedValue = 0;       // ค่าตอนแม่เหล็กอยู่ใกล้ (ประตูปิด)
bool doorOpen = false;
int  opens = 0;

void setup() {
  pinMode(BUZZER, OUTPUT);
  pinMode(LED, OUTPUT);
  Serial.begin(9600);

  Serial.println("เอาแม่เหล็กแนบเซนเซอร์ไว้ (ประตูปิด) รอ 3 วินาที...");
  delay(3000);
  closedValue = analogRead(PIN_A);
  Serial.print("ค่าตอนประตูปิด = ");
  Serial.println(closedValue);
  Serial.println("พร้อมแล้ว ลองดึงแม่เหล็กออก");
}

void loop() {
  int value = analogRead(PIN_A);
  bool open = (abs(value - closedValue) > 100);   // ต่างจากตอนปิดมาก = ถูกเปิด

  if (open && !doorOpen) {
    doorOpen = true;
    opens++;
    Serial.print("!! ประตูถูกเปิด ครั้งที่ ");
    Serial.print(opens);
    Serial.println(" !!");
    digitalWrite(LED, HIGH);
    for (int i = 0; i < 5; i++) { beep(2200, 120); delay(80); }
  }
  else if (!open && doorOpen) {
    doorOpen = false;
    digitalWrite(LED, LOW);
    Serial.println("ประตูปิดแล้ว");
    beep(900, 150);
  }
  delay(80);
}

void beep(int freq, int ms) {
  tone(BUZZER, freq);
  delay(ms);
  noTone(BUZZER);
}

