// ลองทั้งขั้ว N และ S จะพบว่ารีดสวิตช์ติดทั้งสองขั้ว ต่างจากเซนเซอร์ฮอลล์

#include <Wire.h>
#include <LiquidCrystal_I2C.h>
LiquidCrystal_I2C lcd(0x27, 16, 2);

const int PIN_A  = A0;
const int BUZZER = 8;

int  closedValue = 0;
bool doorOpen = false;
int  opens = 0;

void setup() {
  pinMode(BUZZER, OUTPUT);
  lcd.init(); lcd.backlight();

  lcd.print("Put magnet on");
  lcd.setCursor(0, 1);
  lcd.print("sensor... 3 sec");
  delay(3000);
  closedValue = analogRead(PIN_A);           // จำค่าตอนประตูปิด
  lcd.clear();
  lcd.print("Door CLOSED");
  lcd.setCursor(0, 1);
  lcd.print("Opened 0 times");
}

void loop() {
  int value = analogRead(PIN_A);
  bool open = (abs(value - closedValue) > 100);

  if (open && !doorOpen) {
    doorOpen = true;
    opens++;
    lcd.setCursor(0, 0);
    lcd.print("** DOOR OPEN **");
    lcd.setCursor(0, 1);
    lcd.print("Opened ");
    lcd.print(opens);
    lcd.print(" times   ");
    for (int i = 0; i < 5; i++) { tone(BUZZER, 2200, 120); delay(200); }
  }
  else if (!open && doorOpen) {
    doorOpen = false;
    lcd.setCursor(0, 0);
    lcd.print("Door CLOSED    ");
    tone(BUZZER, 900, 150);
  }
  delay(80);
}

