//           ปุ่มกด ขาหนึ่ง->D2 อีกขา->GND | บัซเซอร์ +->D8, -->GND

const int R = 9, G = 10, B = 11;
const int BUTTON = 2;
const int BUZZER = 8;

int  mode = 0;                       // 0 = รุ้ง, 1 = หายใจ, 2 = ไฟตำรวจ
bool lastState = HIGH;

void setup() {
  pinMode(R, OUTPUT); pinMode(G, OUTPUT); pinMode(B, OUTPUT);
  pinMode(BUTTON, INPUT_PULLUP);
  pinMode(BUZZER, OUTPUT);
  Serial.begin(9600);
  Serial.println("กดปุ่มเพื่อเปลี่ยนโหมดไฟ");
  Serial.println("โหมด 0 : รุ้ง");
}

void loop() {
  checkButton();

  if (mode == 0) rainbow();
  else if (mode == 1) breathe();
  else police();
}

void checkButton() {
  bool now = digitalRead(BUTTON);
  if (lastState == HIGH && now == LOW) {       // จังหวะที่เพิ่งกดลง
    mode = (mode + 1) % 3;
    Serial.print("โหมด ");
    Serial.print(mode);
    Serial.println(mode == 0 ? " : รุ้ง" : (mode == 1 ? " : หายใจ" : " : ไฟตำรวจ"));
    tone(BUZZER, 1500, 60);
    delay(50);
  }
  lastState = now;
}

void setColor(int r, int g, int b) {
  analogWrite(R, r); analogWrite(G, g); analogWrite(B, b);
}

void rainbow() {                              // ไล่สีต่อเนื่องทีละขั้น
  static int h = 0;
  h = (h + 2) % 360;
  int s = h / 60, f = (h % 60) * 255 / 60;
  if (s == 0) setColor(255, f, 0);
  else if (s == 1) setColor(255 - f, 255, 0);
  else if (s == 2) setColor(0, 255, f);
  else if (s == 3) setColor(0, 255 - f, 255);
  else if (s == 4) setColor(f, 0, 255);
  else setColor(255, 0, 255 - f);
  delay(15);
  checkButton();
}

void breathe() {                              // สว่างขึ้นแล้วหรี่ลงช้า ๆ
  for (int i = 0; i <= 255; i += 5) { setColor(0, 0, i); delay(12); checkButton(); if (mode != 1) return; }
  for (int i = 255; i >= 0; i -= 5) { setColor(0, 0, i); delay(12); checkButton(); if (mode != 1) return; }
}

void police() {                               // แดงน้ำเงินสลับเร็ว
  for (int i = 0; i < 3; i++) { setColor(255, 0, 0); delay(70); setColor(0, 0, 0); delay(50); checkButton(); if (mode != 2) return; }
  for (int i = 0; i < 3; i++) { setColor(0, 0, 255); delay(70); setColor(0, 0, 0); delay(50); checkButton(); if (mode != 2) return; }
}

